<body>
<div class="app">
  <div class="container">
    <header>
      <div class="brand"><span>●</span> Pomofocus</div>
      <div class="head-actions">
        <button class="btn chart" aria-label="statistics">▥</button>
        <button class="btn gear" aria-label="settings">⚙</button>
        <button class="btn user" aria-label="account">●</button>
        <button class="btn dots" aria-label="menu">⋮</button>
      </div>
    </header>

    <section class="timer-card">
      <div class="tabs">
        <button class="btn active" data-mode="pomodoro">Pomodoro</button>
        <button class="btn" data-mode="short">Short Break</button>
        <button class="btn" data-mode="long">Long Break</button>
      </div>
      <div class="time" id="time">25:00</div>
      <button class="btn start" id="start">START</button>
      <button class="btn next" id="next">▶</button>
    </section>

    <div class="session">
      <div class="num">#1</div>
      <div id="sessionText">Time to focus!</div>
    </div>

    <section class="tasks">
      <div class="tasks-head">
        <h2>Tasks</h2>
        <button class="btn more" aria-label="task menu">⋮</button>
      </div>
      <div class="rule"></div>
      <div id="taskList"></div>
      <button class="btn add-task" id="addTask">⊕ &nbsp;Add Task</button>
      <div class="summary" id="summary" style="display:none">
        <span>Pomos: <b id="pomos">0</b> / <b id="pomoTotal">1</b></span>
        <span>Finish At: <b id="finish">14:57</b> <small>(0.4h)</small></span>
      </div>
    </section>

    <section class="info">
      <h1>An online Pomodoro Timer to boost<br>your productivity</h1>
      <h2>What is Pomofocus?</h2>
      <div class="underline"></div>
      <p>Pomofocus is a customizable pomodoro timer that works on desktop &amp; mobile browser. The aim of this app is to help you focus on any task you are working on, such as study, writing, or coding. This app is inspired by <strong>Pomodoro Technique</strong> which is a time management method developed by Francesco Cirillo.</p>
    </section>
  </div>
</div>

<script>
  const body=document.body;
  const timeEl=document.getElementById('time');
  const sessionText=document.getElementById('sessionText');
  const startBtn=document.getElementById('start');
  const addBtn=document.getElementById('addTask');
  const list=document.getElementById('taskList');
  const summary=document.getElementById('summary');
  let mode='pomodoro', seconds=1500, running=false, timer=null, task=null, editor=null;

  const modes={
    pomodoro:{seconds:1500,text:'Time to focus!',cls:''},
    short:{seconds:300,text:'Time for a break!',cls:'break'},
    long:{seconds:900,text:'Time for a break!',cls:'long'}
  };
  function renderTime(){
    let m=Math.floor(seconds/60),s=seconds%60;
    timeEl.textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
  }
  function setMode(newMode){
    if(running)return;
    mode=newMode; seconds=modes[mode].seconds;
    body.className=modes[mode].cls;
    document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));
    sessionText.textContent=modes[mode].text;
    renderTime();
  }
  document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));

  function runTimer(){
    running=true; startBtn.textContent='PAUSE'; startBtn.style.width='300px';
    document.getElementById('next').style.display='inline-block';
    timer=setInterval(()=>{
      if(seconds>0){seconds--;renderTime()}
      else stopTimer();
    },1000);
  }
  function stopTimer(){
    clearInterval(timer);timer=null;running=false;startBtn.textContent='START';
    document.getElementById('next').style.display='none';
  }
  startBtn.onclick=()=>{
    if(running){stopTimer();return}
    runTimer();
  };
  document.getElementById('next').onclick=()=>{seconds=0;renderTime();stopTimer()};

  function makeEditor(){
    editor=document.createElement('div');
    editor.className='editor';
    editor.innerHTML=`
      <div class="editor-main">
        <input class="task-input" id="taskInput" placeholder="What are you working on?" autofocus>
        <div class="estimate">Est Pomodoros</div>
        <div class="counter-row">
          <div class="counter">1</div><button class="btn arrow up"></button><button class="btn arrow down"></button>
        </div>
        <div class="links">+ Add Note &nbsp; + Add Project <span class="lock">▣</span></div>
      </div>
      <div class="editor-actions">
        <button class="btn cancel">Cancel</button>
        <button class="btn save">Save</button>
      </div>`;
    list.appendChild(editor);
    editor.querySelector('.cancel').onclick=()=>{editor.remove();editor=null;addBtn.style.display='block'};
    editor.querySelector('.save').onclick=saveTask;
    setTimeout(()=>document.getElementById('taskInput').focus(),20);
  }
  addBtn.onclick=()=>{
    addBtn.style.display='none';makeEditor();
    setTimeout(()=>window.scrollTo({top:520,behavior:'instant'}),30);
  };
  function saveTask(){
    const val=document.getElementById('taskInput').value.trim();
    if(!val)return;
    task=val;
    editor.remove();editor=null;
    const card=document.createElement('div');
    card.className='task-card';
    card.innerHTML=`<button class="btn task-check">✓</button><div class="task-name">${val}</div><div class="task-count">0 / 1</div><button class="btn task-menu">⋮</button>`;
    list.prepend(card);
    card.querySelector('.task-check').onclick=()=>completeTask(card);
    sessionText.textContent=val;
    summary.style.display='flex';
    addBtn.style.display='block';
    makeEditor();
    window.scrollTo({top:520,behavior:'instant'});
  }
  function completeTask(card){
    card.querySelector('.task-check').style.color='#d78391';
    card.querySelector('.task-name').style.textDecoration='line-through';
    card.querySelector('.task-name').style.color='#aaa';
    document.getElementById('pomos').textContent='0';
    document.getElementById('pomoTotal').textContent='0';
    document.getElementById('finish').textContent='14:32';
    const done=document.createElement('div');
    done.className='finished';
    done.innerHTML=`<span>You've finished all your tasks for<br>today 🎉</span><button class="btn clear">Clear Tasks</button>`;
    document.querySelector('.tasks').appendChild(done);
    done.querySelector('.clear').onclick=()=>{card.remove();done.remove();summary.style.display='none';sessionText.textContent='Time to focus!';task=null};
  }
</script>
</body>
</html>
